INSERT INTO public.vocabulary_words (
  category, word, phonetic, part_of_speech,
  meaning, example, example_translation,
  sentence_paraphrase, paraphrases, collocations, word_family, memory_tip
) VALUES (
  'Academic Discussion & Discourse (Writing Task 3)', 'Advocate', '/ˈæd.və.keɪt/', 'verb / noun',
  'To publicly recommend or support a policy, cause, or proposal [VI: Ủng hộ, tán thành công khai; người chủ trương]', 'Several education researchers advocate for replacing standardized exams with project-based assessments.', 'Nhiều nhà nghiên cứu giáo dục ủng hộ việc thay thế các kỳ thi chuẩn hóa bằng đánh giá dựa trên dự án.',
  'Researchers demonstrated that advocate significantly affected observed outcomes.', '["champion", "endorse", "promote", "support"]'::jsonb, '["advocate for reform", "staunch advocate", "strongly advocate"]'::jsonb, '["advocate (ver.)", "advocateion (n.)", "advocateive (adj.)"]'::jsonb, 'Advocate (verb / noun) = Ủng hộ, tán thành công khai; người chủ trương - nhớ ngữ cảnh học thuật TOEFL'
)
