INSERT INTO public.vocabulary_words (
  category, word, phonetic, part_of_speech,
  meaning, example, example_translation,
  sentence_paraphrase, paraphrases, collocations, word_family, memory_tip
) VALUES (
  'Academic Discussion & Discourse (Writing Task 3)', 'Substantiate', '/səbˈstæn.ʃi.eɪt/', 'verb',
  'To provide evidence or factual proof to demonstrate the truth of a claim [VI: Chứng minh, củng cố luận điểm bằng bằng chứng cụ thể]', 'The author fails to substantiate the claim that remote learning diminishes student engagement.', 'Tác giả đã không thể đưa ra bằng chứng chứng minh cho tuyên bố rằng học từ xa làm giảm sự gắn kết của học sinh.',
  'Researchers demonstrated that substantiate significantly affected observed outcomes.', '["corroborate", "validate", "verify", "authenticate"]'::jsonb, '["substantiate a claim", "substantiate findings"]'::jsonb, '["substantiate (ver.)", "substantiateion (n.)", "substantiateive (adj.)"]'::jsonb, 'Substantiate (verb) = Chứng minh, củng cố luận điểm bằng bằng chứng cụ thể - nhớ ngữ cảnh học thuật TOEFL'
)
