  meaning = EXCLUDED.meaning,
  example = EXCLUDED.example,
  example_translation = EXCLUDED.example_translation,
  sentence_paraphrase = EXCLUDED.sentence_paraphrase,
  paraphrases = EXCLUDED.paraphrases,
