INSERT INTO public.vocabulary_words (
  category, word, phonetic, part_of_speech,
  meaning, example, example_translation,
  sentence_paraphrase, paraphrases, collocations, word_family, memory_tip
) VALUES (
  'Academic Discussion & Discourse (Writing Task 3)', 'Contradict', '/ˌkɒn.trəˈdɪkt/', 'verb',
  'To assert the opposite of a statement or provide contrary evidence [VI: Mâu thuẫn với, phản bác lại, trái ngược với]', 'The recent archaeological discovery contradicts established theories about prehistoric trade routes.', 'Phát hiện khảo cổ gần đây mâu thuẫn với các lý thuyết đã có về các tuyến đường thương mại thời tiền sử.',
  'Researchers demonstrated that contradict significantly affected observed outcomes.', '["refute", "counter", "dispute", "oppose"]'::jsonb, '["directly contradict", "contradict evidence"]'::jsonb, '["contradict (ver.)", "contradiction (n.)", "contradictive (adj.)"]'::jsonb, 'Contradict (verb) = Mâu thuẫn với, phản bác lại, trái ngược với - nhớ ngữ cảnh học thuật TOEFL'
)
ON CONFLICT (category, word) DO UPDATE SET
