  meaning = EXCLUDED.meaning,
  example = EXCLUDED.example,
  example_translation = EXCLUDED.example_translation,
  sentence_paraphrase = EXCLUDED.sentence_paraphrase,
  paraphrases = EXCLUDED.paraphrases,
  collocations = EXCLUDED.collocations,
  word_family = EXCLUDED.word_family,
  memory_tip = EXCLUDED.memory_tip;

INSERT INTO public.vocabulary_words (
  category, word, phonetic, part_of_speech,
  meaning, example, example_translation,
  sentence_paraphrase, paraphrases, collocations, word_family, memory_tip
) VALUES (
  'Academic Discussion & Discourse (Writing Task 3)', 'Synthesize', '/ˈsɪn.θə.saɪz/', 'verb',
  'To combine various ideas or data points to produce a cohesive conclusion [VI: Tổng hợp, kết hợp các nguồn dữ liệu thành một thể thống nhất]', 'Students are required to synthesize diverse perspectives from both the lecture and the assigned scholarly readings.', 'Sinh viên được yêu cầu tổng hợp các góc nhìn đa dạng từ cả bài giảng và các tài liệu đọc học thuật được giao.',
  'Researchers demonstrated that synthesize significantly affected observed outcomes.', '["integrate", "consolidate", "amalgamate"]'::jsonb, '["synthesize information", "synthesize findings"]'::jsonb, '["synthesize (ver.)", "synthesizeion (n.)", "synthesizeive (adj.)"]'::jsonb, 'Synthesize (verb) = Tổng hợp, kết hợp các nguồn dữ liệu thành một thể thống nhất - nhớ ngữ cảnh học thuật TOEFL'
)
ON CONFLICT (category, word) DO UPDATE SET
