  memory_tip = EXCLUDED.memory_tip;

INSERT INTO public.vocabulary_words (
  category, word, phonetic, part_of_speech,
  meaning, example, example_translation,
  sentence_paraphrase, paraphrases, collocations, word_family, memory_tip
) VALUES (
  'Academic Discussion & Discourse (Writing Task 3)', 'Concede', '/kənˈsiːd/', 'verb',
  'To admit that something is true or valid after first denying or resisting it [VI: Thừa nhận (nhượng bộ trong tranh luận), công nhận một luận điểm]', 'Although I support renewable energy, I must concede that solar farms require vast territorial footprints.', 'Mặc dù ủng hộ năng lượng tái tạo, tôi phải thừa nhận rằng các trang trại điện mặt trời đòi hỏi diện tích đất đai khổng lồ.',
  'Researchers demonstrated that concede significantly affected observed outcomes.', '["acknowledge", "grant", "yield", "admit"]'::jsonb, '["concede a point", "concede defeat"]'::jsonb, '["concede (ver.)", "concedeion (n.)", "concedeive (adj.)"]'::jsonb, 'Concede (verb) = Thừa nhận (nhượng bộ trong tranh luận), công nhận một luận điểm - nhớ ngữ cảnh học thuật TOEFL'
)
