) VALUES (
  'Academic Discussion & Discourse (Writing Task 3)', 'Pragmatic', '/præɡˈmæt.ɪk/', 'adjective',
  'Dealing with matters sensibly and realistically based on practical considerations [VI: Thực tế, mang tính thực tiễn, trọng thực dụng]', 'A pragmatic approach to urban congestion combines subway infrastructure with congestion pricing.', 'Một cách tiếp cận thực tế đối với ùn tắc đô thị là kết hợp hạ tầng tàu điện ngầm với phí chống tắc đường.',
  'Researchers demonstrated that pragmatic significantly affected observed outcomes.', '["practical", "realistic", "utilitarian"]'::jsonb, '["pragmatic approach", "pragmatic solution"]'::jsonb, '["pragmatic (adj.)", "pragmatly (adv.)", "pragmatness (n.)"]'::jsonb, 'Pragmatic (adjective) = Thực tế, mang tính thực tiễn, trọng thực dụng - nhớ ngữ cảnh học thuật TOEFL'
)
