) VALUES (
  'Academic Discussion & Discourse (Writing Task 3)', 'Precedent', '/ˈpres.ɪ.dənt/', 'noun',
  'An earlier event or action that serves as an exemplar or guide [VI: Tiền lệ, khuôn mẫu đã có từ trước]', 'The Supreme Court ruling set an important legal precedent for environmental regulatory compliance.', 'Phán quyết của Tòa án Tối cao đã thiết lập một tiền lệ pháp lý quan trọng cho việc tuân thủ quy định môi trường.',
  'Researchers demonstrated that precedent significantly affected observed outcomes.', '["benchmark", "exemplar", "criterion"]'::jsonb, '["set a precedent", "historical precedent"]'::jsonb, '["precedent (nou.)", "precedental (adj.)", "precedentize (v.)"]'::jsonb, 'Precedent (noun) = Tiền lệ, khuôn mẫu đã có từ trước - nhớ ngữ cảnh học thuật TOEFL'
)
