INSERT INTO public.vocabulary_words (
  category, word, phonetic, part_of_speech,
  meaning, example, example_translation,
  sentence_paraphrase, paraphrases, collocations, word_family, memory_tip
) VALUES (
  'Academic Discussion & Discourse (Writing Task 3)', 'Divergent', '/daɪˈvɜː.dʒənt/', 'adjective',
  'Tending to be different or develop in distinct directions [VI: Bất đồng, phân kỳ, rẽ sang các hướng khác nhau]', 'Economists hold sharply divergent views on how central bank interest rates impact job creation.', 'Các nhà kinh tế học có quan điểm bất đồng gay gắt về việc lãi suất ngân hàng trung ương tác động như thế nào đến việc tạo việc làm.',
  'Researchers demonstrated that divergent significantly affected observed outcomes.', '["disparate", "conflicting", "deviating"]'::jsonb, '["divergent opinions", "divergent paths"]'::jsonb, '["divergent (adj.)", "divergently (adv.)", "divergentness (n.)"]'::jsonb, 'Divergent (adjective) = Bất đồng, phân kỳ, rẽ sang các hướng khác nhau - nhớ ngữ cảnh học thuật TOEFL'
)
