) VALUES (
  'Academic Discussion & Discourse (Writing Task 3)', 'Corroborate', '/kəˈrɒb.ə.reɪt/', 'verb',
  'To confirm or give support to a statement or theory with proof [VI: Xác thực, củng cố thêm bằng chứng khẳng định độ tin cậy]', 'Satellite radar scans corroborate the field team''s discovery of an underground Roman aqueduct.', 'Dữ liệu quét radar vệ tinh đã xác thực phát hiện của đội thực địa về một cây cầu dẫn nước La Mã dưới lòng đất.',
  'Researchers demonstrated that corroborate significantly affected observed outcomes.', '["confirm", "substantiate", "validate"]'::jsonb, '["corroborate evidence", "corroborate findings"]'::jsonb, '["corroborate (ver.)", "corroborateion (n.)", "corroborateive (adj.)"]'::jsonb, 'Corroborate (verb) = Xác thực, củng cố thêm bằng chứng khẳng định độ tin cậy - nhớ ngữ cảnh học thuật TOEFL'
)
