) VALUES (
  'Academic Discussion & Discourse (Writing Task 3)', 'Paradox', '/ˈpær.ə.dɒks/', 'noun',
  'A seemingly absurd or self-contradictory statement that proves true [VI: Nghịch lý, điều tưởng chừng mâu thuẫn nhưng lại có thật]', 'The paradox of productivity improvements is that automation often creates new specialized demands for human labor.', 'Nghịch lý của cải thiện năng suất là việc tự động hóa thường tạo ra những nhu cầu chuyên môn mới cho lao động con người.',
  'Researchers demonstrated that paradox significantly affected observed outcomes.', '["contradiction", "anomaly", "oxymoron"]'::jsonb, '["apparent paradox", "unravel a paradox"]'::jsonb, '["paradox (nou.)", "paradoxal (adj.)", "paradoxize (v.)"]'::jsonb, 'Paradox (noun) = Nghịch lý, điều tưởng chừng mâu thuẫn nhưng lại có thật - nhớ ngữ cảnh học thuật TOEFL'
)
