  sentence_paraphrase, paraphrases, collocations, word_family, memory_tip
) VALUES (
  'Academic Discussion & Discourse (Writing Task 3)', 'Empower', '/ɪmˈpaʊ.ər/', 'verb',
  'To give someone authority or confidence to act [VI: Trao quyền, tiếp thêm năng lực và sự tự tin]', 'Interactive workshops empower undergraduate researchers to conduct independent investigations.', 'Các hội thảo tương tác trao quyền cho sinh viên đại học thực hiện các cuộc điều tra độc lập.',
  'Researchers demonstrated that empower significantly affected observed outcomes.', '["authorize", "enable", "emancipate"]'::jsonb, '["empower students", "empower citizens"]'::jsonb, '["empower (ver.)", "empowerion (n.)", "empowerive (adj.)"]'::jsonb, 'Empower (verb) = Trao quyền, tiếp thêm năng lực và sự tự tin - nhớ ngữ cảnh học thuật TOEFL'
)
