  sentence_paraphrase, paraphrases, collocations, word_family, memory_tip
) VALUES (
  'Academic Discussion & Discourse (Writing Task 3)', 'Refute', '/rɪˈfjuːt/', 'verb',
  'To prove a statement or theory to be wrong or false [VI: Bác bỏ, chứng minh điều gì là sai]', 'The scientist published lab findings that refute the outdated hypothesis.', 'Nhà khoa học đã công bố các phát hiện phòng thí nghiệm bác bỏ giả thuyết lỗi thời.',
  'Researchers demonstrated that refute significantly affected observed outcomes.', '["disprove", "debunk", "counter"]'::jsonb, '["refute allegations", "conclusively refute"]'::jsonb, '["refute (ver.)", "refuteion (n.)", "refuteive (adj.)"]'::jsonb, 'Refute (verb) = Bác bỏ, chứng minh điều gì là sai - nhớ ngữ cảnh học thuật TOEFL'
)
