-- Thông báo hoàn tất: Đã nạp thành công hơn 1,000 từ vựng TOEFL 2026 vào Supabase!
SELECT category, count(*) AS total_words 
FROM public.vocabulary_words 
GROUP BY category 
ORDER BY total_words DESC;
